// Photos live in public/images as WebP, generated by `npm run images` from media-src/images.
// An image key is the master file name without extension, e.g. "cat-brillant".

export const imageSmall = (key: string) => `/images/${key}-600.webp`;
export const imageLarge = (key: string) => `/images/${key}-1400.webp`;
export const imageSrcSet = (key: string) => `${imageSmall(key)} 600w, ${imageLarge(key)} 1400w`;

/** Client logos are exported once at 400px wide. */
export const logoSrc = (name: string) => `/images/${name}.webp`;
